const inputData = input.config();

// ---- DEBUG: show what we got (this is the #1 fix in cases like this)
console.log("RAW inputData:", JSON.stringify(inputData, null, 2));

// Accept multiple possible variable names (because yours changed a few times)
const apiKey = inputData.api;

// message can be stored as "message" or "customReply"
const message = inputData.message || inputData.customReply;

// subject optional — if blank, just reuse message
const subject = inputData.subject || "Hi there";

// conversationId can be "convoid" or "convo_id" or "conversationId"
const conversationId =
  inputData.convoid ||
  inputData.convo_id ||
  inputData.conversationId;

// linkedInAccountId can be "sender_id" or "senderid"
const linkedInAccountIdRaw =
  inputData.sender_id ||
  inputData.senderid ||
  inputData.linkedInAccountId;

const linkedInAccountId = Number(linkedInAccountIdRaw);

// ---- HARD VALIDATION so you get a useful error BEFORE calling HeyReach
if (!apiKey) throw new Error("Missing api (HeyReach API key).");
if (!message) throw new Error("Missing message/customReply.");
if (!conversationId) throw new Error("Missing conversationId (convoid/convo_id).");
if (!linkedInAccountIdRaw) throw new Error("Missing sender_id (LinkedIn account id).");
if (Number.isNaN(linkedInAccountId)) {
  throw new Error(`sender_id must be a number. Got: ${linkedInAccountIdRaw}`);
}

// ---- REQUEST
const url = "https://api.heyreach.io/api/public/inbox/SendMessage";

const body = {
  message,
  subject,
  conversationId,
  linkedInAccountId,
};

console.log("SENDING body:", JSON.stringify(body, null, 2));

const response = await fetch(url, {
  method: "POST",
  headers: {
    "X-API-KEY": apiKey,
    "Content-Type": "application/json",
    "Accept": "text/plain",
  },
  body: JSON.stringify(body),
});

const text = await response.text();

console.log("STATUS:", response.status);
console.log("RESPONSE:", text);

if (!response.ok) {
  throw new Error(`HeyReach error ${response.status}: ${text}`);
}

return { ok: true, status: response.status, response: text, sentBody: body };
